import{_ as a,o as t,c as l,a2 as i}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"Ceph RGW Refactoring Meeting 2024-10-23","description":"","frontmatter":{"title":"Ceph RGW Refactoring Meeting 2024-10-23","date":"2024-10-23T00:00:00.000Z","updated":"2024-10-25T00:00:00.000Z","tags":["Ceph","RGW","Bucket Sync","Keystone Cache","Multi-Part Upload"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2024/Ceph_RGW_Refactoring_Meeting_2024-10-23.md","filePath":"posts/2024/Ceph_RGW_Refactoring_Meeting_2024-10-23.md","lastUpdated":1780460162000}'),o={name:"posts/2024/Ceph_RGW_Refactoring_Meeting_2024-10-23.md"};function n(r,e,s,h,c,p){return t(),l("div",null,[...e[0]||(e[0]=[i('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议主题-ceph存储系统中的桶同步错误处理与keystone缓存问题" tabindex="-1">会议主题：Ceph存储系统中的桶同步错误处理与Keystone缓存问题 <a class="header-anchor" href="#会议主题-ceph存储系统中的桶同步错误处理与keystone缓存问题" aria-label="Permalink to &quot;会议主题：Ceph存储系统中的桶同步错误处理与Keystone缓存问题&quot;">​</a></h4><h4 id="主要讨论内容" tabindex="-1">主要讨论内容： <a class="header-anchor" href="#主要讨论内容" aria-label="Permalink to &quot;主要讨论内容：&quot;">​</a></h4><ol><li><p><strong>桶同步错误处理机制</strong>：</p><ul><li>Shila介绍了Ceph分布式存储系统中桶同步过程中错误的重试机制，目前仅在桶分片级别进行全同步或增量同步时重试。</li><li>讨论了在数据同步过程中，即使桶分片处理成功，但由于网络超时等原因，从远程区域获取S3对象可能失败的同步问题。</li><li>提出了为失败的对象同步引入类似的重试机制，但具体实现细节尚不明确。</li></ul></li><li><p><strong>错误报告处理</strong>：</p><ul><li>讨论了处理失败对象同步错误报告的方法，建议在RGW桶同步单个条目CR中写入和读取omap，类似于数据同步错误报告。</li><li>需要进一步讨论和明确如何在桶分片增量同步CR例程中重试这些对象同步。</li></ul></li><li><p><strong>Keystone缓存问题</strong>：</p><ul><li>Mark提到了Keystone缓存在多部分上传过程中可能导致的请求风暴问题，这可能导致Keystone崩溃。</li><li>讨论了Keystone缓存未命中时，多个RGW请求可能同时访问Keystone，导致缓存未更新的问题。</li><li>需要进一步研究和实现缓存未命中时的处理机制，以防止重复请求Keystone。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项： <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项：&quot;">​</a></h4><ul><li>需要进一步研究和明确桶同步失败对象的重试机制的具体实现。</li><li>Keystone缓存问题需要优先处理，以防止对Keystone的重复请求导致系统崩溃。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h4><ul><li>Shila将继续在跟踪器中记录桶同步错误处理的详细需求和实现细节。</li><li>Mark将协调内部团队，尝试找到可以处理Keystone缓存问题的开发人员，并与Ceph社区合作进行实现和测试。</li><li>下周会议将继续讨论跨区域组复制的优化和加密对象复制操作的测试覆盖问题。</li></ul><h4 id="参会人员" tabindex="-1">参会人员： <a class="header-anchor" href="#参会人员" aria-label="Permalink to &quot;参会人员：&quot;">​</a></h4><ul><li>Shila</li><li>Mark</li><li>Marcus</li><li>其他相关开发和测试人员</li></ul><h4 id="备注" tabindex="-1">备注： <a class="header-anchor" href="#备注" aria-label="Permalink to &quot;备注：&quot;">​</a></h4><ul><li>会议中提到的技术细节涉及Ceph的多个组件和机制，包括RADOS、omap、RGW、Keystone缓存等，需要相关领域的专业知识进行深入理解和实现。</li></ul>',12)])])}const _=a(o,[["render",n]]);export{u as __pageData,_ as default};
